function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) { return sql(JSON.stringify(value ?? {})) + '::jsonb'; }
const body = $json.body || $json;
const publicationJobId = String(body.publicationJobId || body.publication_job_id || '').trim();
const assetId = String(body.assetId || body.asset_id || '').trim();
const reviewNotes = String(body.reviewNotes || body.review_notes || 'Selected for publication job via Avatares AI Console').trim();
let reviewMetadata = null;
try {
  const parsed = JSON.parse(reviewNotes);
  if (parsed && typeof parsed === 'object' && parsed.contractVersion === 'publication-quality-review-v1') reviewMetadata = parsed;
} catch {}
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuidRegex.test(publicationJobId) || !assetId) {
  return [{ json: { query: "SELECT false AS ok, 'publicationJobId must be a valid UUID and assetId is required' AS error;" } }];
}
const query = `
WITH job AS (
  SELECT *
  FROM publication_jobs
  WHERE publication_job_id = ${sql(publicationJobId)}::uuid
  LIMIT 1
), asset AS (
  SELECT *
  FROM canonical_asset_registry
  WHERE asset_id = ${sql(assetId)}
  LIMIT 1
), validation AS (
  SELECT CASE
    WHEN NOT EXISTS (SELECT 1 FROM job) THEN 'Publication job not found'
    WHEN NOT EXISTS (SELECT 1 FROM asset) THEN 'Asset not found'
    WHEN (SELECT avatar FROM asset) <> (SELECT avatar FROM job) THEN 'Asset avatar does not match publication job'
    WHEN (SELECT scene FROM asset) <> (SELECT scene FROM job) THEN 'Asset scene does not match publication job'
    ELSE NULL
  END AS error
), selected_asset AS (
  UPDATE canonical_asset_registry car
  SET
    status = 'selected',
    is_canonical = false,
    review_notes = ${sql(reviewNotes)},
    metadata = COALESCE(car.metadata, '{}'::jsonb) || jsonb_build_object(
      'status', 'selected',
      'isCanonical', false,
      'selectedForPublicationJobId', ${sql(publicationJobId)},
      'selectedForPublicationAt', now(),
      'publicationQualityReview', ${sqlJson(reviewMetadata)}
    )
  WHERE car.asset_id = ${sql(assetId)}
    AND (SELECT error FROM validation) IS NULL
  RETURNING car.*
), publication_update AS (
  UPDATE publication_jobs pj
  SET
    status = 'assets-ready',
    error_message = NULL,
    metadata = COALESCE(pj.metadata, '{}'::jsonb) || jsonb_build_object(
      'selectedAssetId', (SELECT asset_id FROM selected_asset LIMIT 1),
      'selectedAssetObjectPath', (SELECT object_path FROM selected_asset LIMIT 1),
      'selectedAssetBucket', (SELECT bucket FROM selected_asset LIMIT 1),
      'selectedAssetSha256', (SELECT sha256 FROM selected_asset LIMIT 1),
      'selectedAssetAt', now(),
      'selectedAssetReviewNotes', ${sql(reviewNotes)},
      'selectedAssetQualityReview', ${sqlJson(reviewMetadata)}
    ),
    updated_at = now()
  WHERE pj.publication_job_id = ${sql(publicationJobId)}::uuid
    AND EXISTS (SELECT 1 FROM selected_asset)
  RETURNING pj.*
), generated_update AS (
  UPDATE generated_assets ga
  SET
    status = 'approved',
    review_notes = ${sql(reviewNotes)},
    metadata = COALESCE(ga.metadata, '{}'::jsonb) || jsonb_build_object(
      'selectedForPublicationJobId', ${sql(publicationJobId)},
      'selectedForPublicationAt', now()
    ),
    updated_at = now()
  WHERE ga.asset_id = ${sql(assetId)}
  RETURNING ga.*
)
SELECT
  CASE WHEN (SELECT error FROM validation) IS NULL THEN true ELSE false END AS ok,
  (SELECT error FROM validation) AS error,
  (SELECT jsonb_build_object(
    'assetId', asset_id,
    'avatar', avatar,
    'scene', scene,
    'assetType', asset_type,
    'status', status,
    'isCanonical', is_canonical,
    'bucket', bucket,
    'objectPath', object_path,
    'mimeType', mime_type,
    'sha256', sha256,
    'reviewNotes', review_notes,
    'metadata', metadata,
    'qa', metadata->'qa',
    'createdAt', created_at
  ) FROM selected_asset LIMIT 1) AS asset,
  (SELECT jsonb_build_object(
    'publicationJobId', publication_job_id,
    'avatar', avatar,
    'scene', scene,
    'format', format,
    'objective', objective,
    'businessProfile', business_profile,
    'assetType', asset_type,
    'status', status,
    'brief', brief,
    'promptPack', prompt_pack,
    'createdAt', created_at,
    'updatedAt', updated_at
  ) FROM publication_update LIMIT 1) AS job,
  (SELECT generated_asset_id FROM generated_update LIMIT 1) AS "generatedAssetId";
`;
return [{ json: { query } }];

function parse(value) {
  if (value == null) return null;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return null; }
  }
  return value;
}
const row = $input.first()?.json || {};
const ok = row.ok === true || row.ok === 't';
if (!ok) {
  return [{ json: { ok: false, selected: false, error: row.error || 'Publication asset was not selected.' } }];
}
const asset = parse(row.asset);
const job = parse(row.job);
if (!asset?.assetId || !job?.publicationJobId) {
  return [{ json: { ok: false, selected: false, error: 'Selection did not return asset/job metadata.' } }];
}
return [{
  json: {
    ok: true,
    selected: true,
    asset,
    job,
    assetId: asset.assetId,
    publicationJobId: job.publicationJobId,
    publicationStatus: job.status,
    generatedAssetId: row.generatedAssetId || null
  }
}];
